    # Initialize the distance dictionary
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    visited = {}
    path = {}

    # Initialize the path dictionary
    for node in graph:
        path[node] = []

    # Initialize the edge list
    edges = []

    # Function to add edges to the edge list
    def add_edges(node):
        for neighbor, weight in graph[node]:
            edges.append((node, neighbor, weight))

    # Add edges from the source to the edge list
    add_edges(source)

    # Process the nodes until the target is found
    while edges:
        # Get the node with the smallest known distance
        current_node = min(edges, key=lambda x: distances[x[0]])
        if current_node[1] in visited:
            edges.remove(current_node)
            continue
        visited[current_node[1]] = True

        # Update distances and paths to the neighbors
        for neighbor, weight in graph[current_node[1]]:
            if distances[current_node[1]] + weight < distances[neighbor]:
                distances[neighbor] = distances[current_node[1]] + weight
                path[neighbor] = path[current_node[1]].copy()
                path[neighbor].append(current_node[1])
                add_edges(neighbor)

    # Check if the target is reachable
    if target in path:
        return (distances[target], path[target])
    else:
        return (float('inf'), None)

